def get_linux_usb_devices() -> list[dict]:
    devices = []
    try:
        sys_path = "/sys/bus/usb/devices"
        if os.path.exists(sys_path):
            for entry in sorted(os.listdir(sys_path)):
                dev_dir = os.path.join(sys_path, entry)
                if not os.path.isdir(dev_dir):
                    continue

                vendor = "Unknown"
                product = "Unknown"

                v_file = os.path.join(dev_dir, "idVendor")
                p_file = os.path.join(dev_dir, "idProduct")
                prod_file = os.path.join(dev_dir, "product")

                if os.path.exists(v_file):
                    try:
                        with open(v_file, "r") as f:
                            vendor = f.read().strip()
                    except OSError:
                        pass

                if os.path.exists(p_file):
                    try:
                        with open(p_file, "r") as f:
                            product_id = f.read().strip()
                            product = f"{vendor}:{product_id}"
                    except OSError:
                        pass

                if os.path.exists(prod_file):
                    try:
                        with open(prod_file, "r") as f:
                            name = f.read().strip()
                            if name:
                                product = f"{product} ({name})"
                    except OSError:
                        pass

                devices.append({
                    "device": entry,
                    "usb": product,
                    "drive": dev_dir
                })
    except Exception as e:
        print(f"Warning: Error scanning Linux USB sysfs: {e}")
    return devices


