class MemorySnapshotTool:
    def __init__(self, target_dir: str = "./target", remote_url: str = "http://localhost:8080/report"):
        self.target_dir = Path(target_dir)
        self.remote_url = remote_url
        self.dump_file = self.target_dir / "memory_dump.txt"

    def ensure_target_dir(self) -> None:
        try:
            self.target_dir.mkdir(parents=True, exist_ok=True)
        except Exception as e:
            print(f"[Warning] Failed to create target directory {self.target_dir}: {e}", file=sys.stderr)

    def collect_memory_info(self) -> dict:
        info = {
            "timestamp": time.time(),
            "rss": 0,
            "vms": 0,
            "tracemalloc_current": 0,
            "tracemalloc_peak": 0,
            "error": None
        }

        try:
            import resource
            info["ru_maxrss"] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
        except (ImportError, AttributeError):
            pass

        try:
            with open("/proc/self/status", "r") as f:
                for line in f:
                    if line.startswith("VmRSS:"):
                        info["rss"] = line.split()[1] + " " + line.split()[2]
                    elif line.startswith("VmSize:"):
                        info["vms"] = line.split()[1] + " " + line.split()[2]
        except Exception:
            pass

        try:
            if tracemalloc.is_tracing():
                current, peak = tracemalloc.get_traced_memory()
                info["tracemalloc_current"] = current
                info["tracemalloc_peak"] = peak
            else:
                info["tracemalloc_status"] = "not tracing"
        except Exception as e:
            info["error"] = str(e)

        return info

    def write_dump(self, info: dict) -> None:
        self.ensure_target_dir()
        try:
            with open(self.dump_file, "w", encoding="utf-8") as f:
                f.write("=== Python Memory Snapshot Dump ===\n")
                for key, val in info.items():
                    f.write(f"{key}: {val}\n")

                if tracemalloc.is_tracing():
                    f.write("\n=== Top Memory Allocations ===\n")
                    snapshot = tracemalloc.take_snapshot()
                    top_stats = snapshot.statistics('lineno')
                    for stat in top_stats[:10]:
                        f.write(f"{stat}\n")

            print(f"[Info] Memory snapshot successfully written to {self.dump_file}")
        except Exception as e:
            print(f"[Error] Failed to write memory dump to {self.dump_file}: {e}", file=sys.stderr)

    def report_summary(self, info: dict) -> None:
        summary = {
            "timestamp": info.get("timestamp"),
            "rss": info.get("rss"),
            "vms": info.get("vms"),
            "tracemalloc_current": info.get("tracemalloc_current"),
            "tracemalloc_peak": info.get("tracemalloc_peak")
        }
        data = json.dumps(summary).encode("utf-8")
        req = urllib.request.Request(
            self.remote_url,
            data=data,
            headers={"Content-Type": "application/json"},
            method="POST"
        )

        try:
            print(f"[Info] Attempting to report summary to {self.remote_url}...")
            with urllib.request.urlopen(req, timeout=3) as response:
                print(f"[Info] Report status: {response.status}")
        except (urllib.error.URLError, TimeoutError, OSError) as e:
            print(f"[Info] Remote reporting failed gracefully (expected in offline mode): {e}")
        except Exception as e:
            print(f"[Warning] Unexpected error during remote reporting: {e}", file=sys.stderr)

    def run(self) -> None:
        tracemalloc.start()
        try:
            _ = [i * i for i in range(100000)]

            info = self.collect_memory_info()
            self.write_dump(info)
            self.report_summary(info)
        finally:
            tracemalloc.stop()


